const P = [
  ['Mobitrace','14240418673f52ae29a007.74392007'],
  ['Unicopy','35679002689c4f3ba6dd50.31739712'],
  ['Unicopy (backend)','1600517668d38be7f36ba4.51132642']
];
const out = [];
for (const p of P) {
  for (let pg = 1; pg <= 3; pg++) {
    out.push({ json: { name: p[0], pid: p[1], page: pg, url: 'https://api.lokalise.com/api2/projects/' + p[1] + '/keys?filter_untranslated=1&include_translations=1&limit=200&page=' + pg } });
  }
}
return out;

const reqs = $('Config').all();
const res = $input.all();
const per = {};
const errors = [];
const rows = [];
for (let i = 0; i < res.length; i++) {
  const meta = (reqs[i] || { json: {} }).json;
  const r = res[i].json || {};
  const b = r.body || {};
  if (r.statusCode !== 200) { errors.push(meta.name + ' p' + meta.page + ' status ' + r.statusCode); continue; }
  if (!Array.isArray(b.keys)) { errors.push(meta.name + ' p' + meta.page + ' no keys array'); continue; }
  if (!per[meta.name]) { per[meta.name] = { pid: meta.pid, keys: 0, archived: 0, plural: 0, missing_by_locale: {}, no_en: 0 }; }
  const o = per[meta.name];
  for (const k of b.keys) {
    o.keys++;
    if (k.is_archived) { o.archived++; }
    if (k.is_plural) { o.plural++; }
    let en = '';
    const empties = [];
    for (const t of (k.translations || [])) {
      const iso = t.language_iso;
      const txt = (t.translation === null || t.translation === undefined) ? '' : (typeof t.translation === 'object' ? JSON.stringify(t.translation) : String(t.translation));
      if (iso === 'en') { en = txt; continue; }
      if (!txt.trim()) { empties.push(iso); o.missing_by_locale[iso] = (o.missing_by_locale[iso] || 0) + 1; }
    }
    if (!en.trim()) { o.no_en++; }
    if (rows.length < 40) {
      rows.push({ project: meta.name, key_id: k.key_id, key: (k.key_name || {}).web || (k.key_name || {}).other || '', archived: !!k.is_archived, plural: !!k.is_plural, en: en.slice(0, 120), missing: empties.join(',') });
    }
  }
}
return [{ json: { per_project: per, errors: errors, sample_rows: rows } }];
